def transform_d4(grid):
 h,w=len(grid),len(grid[0]); counts=Counter(v for row in grid for v in row); bg=counts.most_common(1)[0][0]; cols={v for row in grid for v in row if v not in (0,bg)}
 if not cols:return [r[:] for r in grid]
 color=max(cols,key=lambda v:sum(x==v for row in grid for x in row)); pts=[(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x==color]
 # all dihedral forms from rotations and mirrors of original points, normalize coords
 forms=set()
 for refl in (False,True):
  for k in range(4):
   q=[]
   for r,c in pts:
    if refl:c=-c
    for _ in range(k):r,c=c,-r
    q.append((r,c))
   mr=min(r for r,c in q); mc=min(c for r,c in q)
   forms.add(tuple(sorted((r-mr,c-mc) for r,c in q)))
 out=[row[:] for row in grid]
 for form in forms:
  ph=max(r for r,c in form)+1; pw=max(c for r,c in form)+1
  for top in range(h-ph+1):
   for left in range(w-pw+1):
    if all(grid[top+dr][left+dc] in (0,color) for dr,dc in form):
     for dr,dc in form:out[top+dr][left+dc]=color
 return out
